actionConfiguration.body:
SELECT
  public.issue19_has_role({{ appsmith.user.email }}, 'document_reviewer') AS can_member,
  public.issue19_has_role({{ appsmith.user.email }}, 'donations_reviewer') AS can_contributor,
  public.issue19_has_role({{ appsmith.user.email }}, 'directory_manager') AS can_directory_manager,
  (public.issue19_has_role({{ appsmith.user.email }}, 'document_reviewer')
   AND public.issue19_has_role({{ appsmith.user.email }}, 'donations_reviewer')
   AND public.issue19_has_role({{ appsmith.user.email }}, 'directory_manager')) AS can_both;
